<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Falling Sand Sandbox</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #090b10;
      --panel: #131720;
      --panel-2: #1a202b;
      --border: #2b3442;
      --text: #edf2f7;
      --muted: #94a0b3;
      --accent: #7dd3fc;
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      min-height: 100%;
      margin: 0;
    }

    body {
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 24px;
      overflow-x: auto;
      background:
        radial-gradient(circle at 50% 0%, #18202d 0, transparent 42%),
        linear-gradient(160deg, #090b10, #0d1118 60%, #080a0e);
      color: var(--text);
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    .app {
      width: 660px;
      text-align: center;
    }

    h1 {
      margin: 0 0 5px;
      font-size: 25px;
      letter-spacing: 0.04em;
    }

    .subtitle {
      margin: 0 0 16px;
      color: var(--muted);
      font-size: 13px;
    }

    .canvas-shell {
      width: 624px;
      margin: 0 auto;
      padding: 11px;
      border: 1px solid var(--border);
      border-radius: 16px;
      background: rgba(19, 23, 32, 0.94);
      box-shadow:
        0 22px 55px rgba(0, 0, 0, 0.48),
        inset 0 1px rgba(255, 255, 255, 0.04);
    }

    #sand {
      display: block;
      width: 600px;
      height: 500px;
      border: 1px solid #354052;
      border-radius: 9px;
      background: #070a0f;
      cursor: crosshair;
      touch-action: none;
      image-rendering: pixelated;
      box-shadow:
        inset 0 0 30px rgba(0, 0, 0, 0.7),
        0 0 0 1px rgba(255, 255, 255, 0.025);
    }

    .controls {
      width: 624px;
      margin: 14px auto 0;
      padding: 13px;
      border: 1px solid var(--border);
      border-radius: 14px;
      background: rgba(19, 23, 32, 0.95);
      box-shadow: 0 12px 35px rgba(0, 0, 0, 0.28);
    }

    .materials,
    .utility {
      display: flex;
      align-items: center;
      justify-content: center;
      flex-wrap: wrap;
      gap: 8px;
    }

    .utility {
      margin-top: 11px;
      padding-top: 11px;
      border-top: 1px solid #29313e;
    }

    button {
      min-height: 39px;
      padding: 8px 13px;
      border: 1px solid #343e4d;
      border-radius: 10px;
      outline: none;
      background: linear-gradient(#222936, #1a202b);
      color: var(--text);
      font: inherit;
      font-size: 13px;
      font-weight: 700;
      cursor: pointer;
      user-select: none;
      transition: transform 100ms ease, border-color 100ms ease, background 100ms ease;
    }

    button:hover {
      border-color: #566276;
      transform: translateY(-1px);
    }

    button:active {
      transform: translateY(1px);
    }

    button.selected {
      border-color: var(--accent);
      background: linear-gradient(#26384a, #1d2b3a);
      box-shadow: 0 0 0 2px rgba(125, 211, 252, 0.13);
    }

    button:focus-visible,
    input:focus-visible {
      box-shadow: 0 0 0 3px rgba(125, 211, 252, 0.25);
    }

    .dot {
      display: inline-block;
      width: 10px;
      height: 10px;
      margin-right: 7px;
      border-radius: 50%;
      vertical-align: -1px;
      box-shadow: 0 0 5px currentColor;
    }

    .sand-dot { color: #f2c55c; background: currentColor; }
    .water-dot { color: #4598f5; background: currentColor; }
    .wall-dot { color: #9299a5; background: currentColor; }
    .acid-dot { color: #77ee63; background: currentColor; }
    .empty-dot {
      color: #798394;
      background: transparent;
      border: 2px solid currentColor;
      box-shadow: none;
    }

    #clear {
      color: #ffb4b4;
    }

    label {
      display: inline-flex;
      align-items: center;
      gap: 7px;
      color: var(--muted);
      font-size: 12px;
      font-weight: 650;
    }

    input[type="range"] {
      width: 90px;
      accent-color: var(--accent);
    }

    .status {
      min-width: 72px;
      color: #b9c3d2;
      font-size: 12px;
    }

    .hint {
      margin: 11px 0 0;
      color: #758196;
      font-size: 11px;
    }
  </style>
</head>
<body>
  <main class="app">
    <h1>Elemental Sandbox</h1>
    <p class="subtitle">Paint matter, build channels, and let gravity do the rest.</p>

    <div class="canvas-shell">
      <canvas id="sand" width="600" height="500" aria-label="Falling sand simulation"></canvas>
    </div>

    <section class="controls" aria-label="Sandbox controls">
      <div class="materials" role="group" aria-label="Materials">
        <button id="mat-sand" class="selected" type="button">
          <span class="dot sand-dot"></span>Sand
        </button>
        <button id="mat-water" type="button">
          <span class="dot water-dot"></span>Water
        </button>
        <button id="mat-wall" type="button">
          <span class="dot wall-dot"></span>Wall
        </button>
        <button id="mat-acid" type="button">
          <span class="dot acid-dot"></span>Acid
        </button>
        <button id="mat-empty" type="button">
          <span class="dot empty-dot"></span>Eraser
        </button>
      </div>

      <div class="utility">
        <button id="toggle" type="button">Pause</button>
        <button id="clear" type="button">Clear grid</button>
        <label>
          Brush
          <input id="brush" type="range" min="1" max="6" value="3">
        </label>
        <label>
          Speed
          <input id="speed" type="range" min="5" max="60" value="30">
        </label>
        <span id="status" class="status">Running</span>
      </div>

      <p class="hint">Drag to paint · Sand sinks through liquids · Acid erodes sand and walls</p>
    </section>
  </main>

  <script>
    (() => {
      "use strict";

      const canvas = document.getElementById("sand");
      const ctx = canvas.getContext("2d", { alpha: false });

      const W = 120;
      const H = 100;
      const CELL_W = canvas.width / W;
      const CELL_H = canvas.height / H;

      const EMPTY = 0;
      const SAND = 1;
      const WATER = 2;
      const WALL = 3;
      const ACID = 4;

      const names = ["empty", "sand", "water", "wall", "acid"];
      const codes = Object.freeze({
        empty: EMPTY,
        sand: SAND,
        water: WATER,
        wall: WALL,
        acid: ACID
      });

      const grid = new Uint8Array(W * H);
      const moved = new Uint8Array(W * H);

      let selected = "sand";
      let running = true;
      let seed = 0x6d2b79f5;
      let painting = false;
      let previousPaintCell = null;
      let lastFrame = performance.now();
      let accumulator = 0;

      const materialButtons = {
        sand: document.getElementById("mat-sand"),
        water: document.getElementById("mat-water"),
        wall: document.getElementById("mat-wall"),
        acid: document.getElementById("mat-acid"),
        empty: document.getElementById("mat-empty")
      };

      const clearButton = document.getElementById("clear");
      const toggleButton = document.getElementById("toggle");
      const brushInput = document.getElementById("brush");
      const speedInput = document.getElementById("speed");
      const status = document.getElementById("status");

      const index = (x, y) => y * W + x;
      const inside = (x, y) => x >= 0 && x < W && y >= 0 && y < H;

      function random() {
        seed ^= seed << 13;
        seed ^= seed >>> 17;
        seed ^= seed << 5;
        return (seed >>> 0) / 4294967296;
      }

      function randomDirections() {
        return random() < 0.5 ? [-1, 1] : [1, -1];
      }

      function moveCell(x, y, nx, ny) {
        const from = index(x, y);
        const to = index(nx, ny);
        grid[to] = grid[from];
        grid[from] = EMPTY;
        moved[to] = 1;
      }

      /*
       * Relocate displaced liquid sideways or downward rather than swapping
       * it upward into the sand's old position. This prevents liquid from
       * climbing through a tall falling sand column.
       */
      function relocateLiquid(tx, ty, liquid) {
        const targetIndex = index(tx, ty);
        if (moved[targetIndex]) return false;

        const dirs = randomDirections();
        const candidates = [
          [tx + dirs[0], ty],
          [tx + dirs[1], ty],
          [tx, ty + 1],
          [tx + dirs[0], ty + 1],
          [tx + dirs[1], ty + 1]
        ];

        for (const [nx, ny] of candidates) {
          if (!inside(nx, ny)) continue;
          const ni = index(nx, ny);
          if (grid[ni] === EMPTY && !moved[ni]) {
            grid[ni] = liquid;
            moved[ni] = 1;
            grid[targetIndex] = EMPTY;
            return true;
          }
        }

        return false;
      }

      function trySandDestination(x, y, nx, ny) {
        if (!inside(nx, ny)) return false;

        const target = grid[index(nx, ny)];

        if (target === EMPTY) {
          moveCell(x, y, nx, ny);
          return true;
        }

        if (target === WATER || target === ACID) {
          if (relocateLiquid(nx, ny, target)) {
            moveCell(x, y, nx, ny);
            return true;
          }
        }

        return false;
      }

      function updateSand(x, y) {
        if (y >= H - 1) return;

        if (trySandDestination(x, y, x, y + 1)) return;

        const dirs = randomDirections();
        if (trySandDestination(x, y, x + dirs[0], y + 1)) return;
        trySandDestination(x, y, x + dirs[1], y + 1);
      }

      function updateFlowingLiquid(x, y) {
        if (y < H - 1 && grid[index(x, y + 1)] === EMPTY) {
          moveCell(x, y, x, y + 1);
          return;
        }

        const dirs = randomDirections();

        if (y < H - 1) {
          const dx1 = x + dirs[0];
          const dx2 = x + dirs[1];

          if (inside(dx1, y + 1) && grid[index(dx1, y + 1)] === EMPTY) {
            moveCell(x, y, dx1, y + 1);
            return;
          }

          if (inside(dx2, y + 1) && grid[index(dx2, y + 1)] === EMPTY) {
            moveCell(x, y, dx2, y + 1);
            return;
          }
        }

        const sx1 = x + dirs[0];
        const sx2 = x + dirs[1];

        if (inside(sx1, y) && grid[index(sx1, y)] === EMPTY) {
          moveCell(x, y, sx1, y);
          return;
        }

        if (inside(sx2, y) && grid[index(sx2, y)] === EMPTY) {
          moveCell(x, y, sx2, y);
        }
      }

      function updateAcid(x, y) {
        const neighbors = [];
        if (y + 1 < H) neighbors.push([x, y + 1]);

        const dirs = randomDirections();
        if (inside(x + dirs[0], y)) neighbors.push([x + dirs[0], y]);
        if (inside(x + dirs[1], y)) neighbors.push([x + dirs[1], y]);

        for (const [nx, ny] of neighbors) {
          const ni = index(nx, ny);
          if (grid[ni] === SAND || grid[ni] === WALL) {
            grid[ni] = EMPTY;
            moved[ni] = 0;
          }
        }

        updateFlowingLiquid(x, y);
      }

      function step() {
        moved.fill(0);

        // Bottom-row-up processing is essential: downward movement goes into
        // an already processed row, so particles cannot fall repeatedly.
        for (let y = H - 1; y >= 0; y--) {
          const leftToRight = random() < 0.5;

          for (let n = 0; n < W; n++) {
            const x = leftToRight ? n : W - 1 - n;
            const i = index(x, y);

            if (moved[i]) continue;

            switch (grid[i]) {
              case SAND:
                updateSand(x, y);
                break;
              case WATER:
                updateFlowingLiquid(x, y);
                break;
              case ACID:
                updateAcid(x, y);
                break;
              case WALL:
              case EMPTY:
              default:
                break;
            }
          }
        }
      }

      function colorFor(type, x, y) {
        const variation = ((x * 31 + y * 17) % 19) - 9;

        switch (type) {
          case SAND:
            return `rgb(${232 + variation}, ${184 + variation}, ${72 + variation / 2})`;
          case WATER:
            return `rgb(${37 + variation / 3}, ${125 + variation}, ${224 + variation})`;
          case WALL:
            return `rgb(${105 + variation}, ${113 + variation}, ${126 + variation})`;
          case ACID:
            return `rgb(${83 + variation / 2}, ${220 + variation}, ${71 + variation / 3})`;
          default:
            return "#080b11";
        }
      }

      function render() {
        ctx.fillStyle = "#080b11";
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        for (let y = 0; y < H; y++) {
          for (let x = 0; x < W; x++) {
            const type = grid[index(x, y)];
            if (type === EMPTY) continue;

            ctx.fillStyle = colorFor(type, x, y);
            ctx.fillRect(
              Math.floor(x * CELL_W),
              Math.floor(y * CELL_H),
              Math.ceil(CELL_W),
              Math.ceil(CELL_H)
            );

            if (type === WATER || type === ACID) {
              ctx.fillStyle = type === WATER
                ? "rgba(170,220,255,0.16)"
                : "rgba(220,255,180,0.18)";
              ctx.fillRect(
                Math.floor(x * CELL_W),
                Math.floor(y * CELL_H),
                Math.ceil(CELL_W),
                1
              );
            }
          }
        }

        const edge = ctx.createLinearGradient(0, 0, 0, canvas.height);
        edge.addColorStop(0, "rgba(255,255,255,0.025)");
        edge.addColorStop(0.8, "rgba(0,0,0,0)");
        edge.addColorStop(1, "rgba(0,0,0,0.24)");
        ctx.fillStyle = edge;
        ctx.fillRect(0, 0, canvas.width, canvas.height);
      }

      function clearGrid() {
        grid.fill(EMPTY);
        moved.fill(0);
        seed = 0x6d2b79f5;
        render();
      }

      function publicSet(x, y, material) {
        x = Math.trunc(Number(x));
        y = Math.trunc(Number(y));

        if (!inside(x, y)) return false;
        if (!Object.prototype.hasOwnProperty.call(codes, material)) {
          throw new TypeError("Unknown material: " + material);
        }

        grid[index(x, y)] = codes[material];
        render();
        return true;
      }

      function publicGet(x, y) {
        x = Math.trunc(Number(x));
        y = Math.trunc(Number(y));
        if (!inside(x, y)) return "empty";
        return names[grid[index(x, y)]];
      }

      function tick(n = 1) {
        n = Math.max(0, Math.trunc(Number(n)) || 0);
        for (let i = 0; i < n; i++) step();
        render();
      }

      window.sim = {
        w: W,
        h: H,
        tick,
        get: publicGet,
        set: publicSet,
        clear: clearGrid
      };

      function selectMaterial(material) {
        selected = material;
        for (const [name, button] of Object.entries(materialButtons)) {
          const active = name === material;
          button.classList.toggle("selected", active);
          button.setAttribute("aria-pressed", String(active));
        }
      }

      for (const [material, button] of Object.entries(materialButtons)) {
        button.addEventListener("click", () => selectMaterial(material));
      }

      clearButton.addEventListener("click", clearGrid);

      toggleButton.addEventListener("click", () => {
        running = !running;
        toggleButton.textContent = running ? "Pause" : "Resume";
        status.textContent = running ? "Running" : "Paused";
        accumulator = 0;
        lastFrame = performance.now();
      });

      function canvasCellFromEvent(event) {
        const rect = canvas.getBoundingClientRect();
        return {
          x: Math.max(0, Math.min(W - 1, Math.floor((event.clientX - rect.left) / rect.width * W))),
          y: Math.max(0, Math.min(H - 1, Math.floor((event.clientY - rect.top) / rect.height * H)))
        };
      }

      function paintCircle(cx, cy) {
        const radius = Math.max(0, Number(brushInput.value) - 1);
        const code = codes[selected];

        for (let dy = -radius; dy <= radius; dy++) {
          for (let dx = -radius; dx <= radius; dx++) {
            if (dx * dx + dy * dy > radius * radius + 0.75) continue;

            const x = cx + dx;
            const y = cy + dy;
            if (inside(x, y)) grid[index(x, y)] = code;
          }
        }
      }

      function paintLine(from, to) {
        const dx = to.x - from.x;
        const dy = to.y - from.y;
        const length = Math.max(Math.abs(dx), Math.abs(dy), 1);

        for (let i = 0; i <= length; i++) {
          paintCircle(
            Math.round(from.x + dx * i / length),
            Math.round(from.y + dy * i / length)
          );
        }

        render();
      }

      canvas.addEventListener("pointerdown", event => {
        painting = true;
        canvas.setPointerCapture(event.pointerId);
        previousPaintCell = canvasCellFromEvent(event);
        paintCircle(previousPaintCell.x, previousPaintCell.y);
        render();
      });

      canvas.addEventListener("pointermove", event => {
        if (!painting) return;
        const current = canvasCellFromEvent(event);
        paintLine(previousPaintCell, current);
        previousPaintCell = current;
      });

      function stopPainting(event) {
        painting = false;
        previousPaintCell = null;
        if (event && canvas.hasPointerCapture(event.pointerId)) {
          canvas.releasePointerCapture(event.pointerId);
        }
      }

      canvas.addEventListener("pointerup", stopPainting);
      canvas.addEventListener("pointercancel", stopPainting);
      canvas.addEventListener("contextmenu", event => event.preventDefault());

      function animate(now) {
        const elapsed = Math.min(100, now - lastFrame);
        lastFrame = now;

        if (running) {
          const interval = 1000 / Number(speedInput.value);
          accumulator += elapsed;

          let steps = 0;
          while (accumulator >= interval && steps < 6) {
            step();
            accumulator -= interval;
            steps++;
          }

          if (steps > 0) render();
        }

        requestAnimationFrame(animate);
      }

      selectMaterial("sand");
      render();
      requestAnimationFrame(animate);
    })();
  </script>
</body>
</html>
